-- Free text reasons, team request
ALTER TABLE "issue_events" DROP CONSTRAINT "issue_events_action_check";--> statement-breakpoint
ALTER TABLE "moderation_decisions" DROP CONSTRAINT "moderation_decisions_reason_check";--> statement-breakpoint
ALTER TABLE "notifications" DROP CONSTRAINT "notifications_template_check";--> statement-breakpoint
ALTER TABLE "moderation_decisions" ALTER COLUMN "reason_code" DROP NOT NULL;--> statement-breakpoint
ALTER TABLE "issue_events" ADD CONSTRAINT "issue_events_action_check" CHECK ("issue_events"."action" IN ('refer', 'escalate', 'record_response', 'mark_in_progress', 'confirm_resolved', 'reopen', 'mark_not_competent', 'mark_not_followed_up', 'close', 'merge', 'claim_resolved')) NOT VALID;--> statement-breakpoint
ALTER TABLE "moderation_decisions" ADD CONSTRAINT "moderation_decisions_reason_check" CHECK (("moderation_decisions"."action" = 'verify' AND "moderation_decisions"."reason_code" IN ('document', 'site_photo', 'second_party', 'news_source', 'reporter_contact') AND "moderation_decisions"."reason_text" IS NULL) OR ("moderation_decisions"."action" = 'reject' AND ("moderation_decisions"."reason_code" IS NULL OR "moderation_decisions"."reason_code" IN ('standard_1', 'standard_2', 'standard_3', 'standard_4', 'standard_5', 'standard_6', 'standard_7', 'standard_8', 'standard_9', 'standard_10', 'standard_11', 'standard_12', 'standard_13', 'out_of_scope')) AND "moderation_decisions"."reason_text" IS NOT NULL) OR ("moderation_decisions"."action" = 'mark_unverifiable' AND ("moderation_decisions"."reason_code" IS NULL OR "moderation_decisions"."reason_code" IN ('no_evidence', 'source_unreachable', 'conflicting_information', 'location_unclear')) AND "moderation_decisions"."reason_text" IS NOT NULL)) NOT VALID;--> statement-breakpoint
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_template_check" CHECK ("notifications"."template" IN ('report_submitted', 'report_in_review', 'report_verified', 'report_unverifiable', 'report_rejected', 'report_merged', 'report_forwarded', 'issue_refer', 'issue_escalate', 'issue_record_response', 'issue_mark_in_progress', 'issue_confirm_resolved', 'issue_reopen', 'issue_mark_not_competent', 'issue_mark_not_followed_up', 'issue_close', 'issue_published', 'issue_claim_resolved', 'complaint_received', 'complaint_decided', 'complaint_appeal_decided', 'demand_publish', 'demand_close', 'demand_reopen', 'demand_update', 'referral_deadline', 'claim_survey', 'reply_received', 'reply_decided')) NOT VALID;